INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Knockout Kings 2002', 'In Knockout Kings 2002, you get to stare down your opponent as the ref runs down the rules, smack your gloves with his, wait for the bell...and let your fists fly. The speed, pain and adrenaline of professional boxing has come to your fingertips. Now it''s time to show the world who''s the champ! Intense, head-to-head action takes it to the mat with the superior technology of PS2.' FROM games WHERE igdb_id = 23462 ON CONFLICT (game_id, language_code) DO NOTHING;
