INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rayman Golf', 'Rayman Golf is a spin-off game that can be played only on mobile phones. It is available in a primitive monochrome version and in a more advanced full-color version. Both were developed and published by Gameloft S.A., and released in 2002. The game is a golf simulator based on the Rayman saga and the main character is controlled on a number of different courses.' FROM games WHERE igdb_id = 61094 ON CONFLICT (game_id, language_code) DO NOTHING;
