INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tactical Ops: Assault on Terror', 'Tactical Ops: Assault on Terror is a first-person shooter video game developed in 2002 by Kamehan Studios and published by Infogrames as a MicroProse title. The game is a standalone retail version of a multiplayer modification of the same name published by Kamehan Studios in 1999 for the game Unreal Tournament. The game features match-based missions in which two teams, themed as Special Forces and terrorists, battle to complete mission objectives and kill their opponents. Upon release, Tactical Ops received mixed to average reviews, with critics faulting the game''s similarities to the non-commercial version and lack of defining features compared to other multiplayer first-person shooters.' FROM games WHERE igdb_id = 8778 ON CONFLICT (game_id, language_code) DO NOTHING;
