INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Magical Quest Starring Mickey & Minnie', 'Disney''s Magical Quest Starring Mickey & Minnie is a GBA remake of the SNES game The Magical Quest Starring Mickey Mouse. In this version Minnie Mouse is added to the game as a playable character, as well as four mini-games for both single-player and multiplayer. The remake also introduces a save feature.' FROM games WHERE igdb_id = 187209 ON CONFLICT (game_id, language_code) DO NOTHING;
