INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lunar Legend', 'You play Alex, a young boy who hopes to one day be a Dragonmaster like his dearly departed hero Dyne. One day, a wizard named Nash comes into town, and needs an escort to a nearby shrine in the woods. You, your childhood friend Luna, and your flying cat-like pet Nall accompany Nash to the shrine, and your adventure begins.' FROM games WHERE igdb_id = 13907 ON CONFLICT (game_id, language_code) DO NOTHING;
