INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battlefield 1942', 'Building upon and vastly refining the ideas from Codename Eagle, Battlefield 1942 let players engage in infantry combat and get behind the wheel of a variety of vehicles from submarines to battleships and bombers. The game introduced the signature Battlefield rock-paper-scissors gameplay, as well as the exciting “Battlefield Moments” people refer to when talking about their unique and unscripted experiences within the multiplayer game.' FROM games WHERE igdb_id = 240 ON CONFLICT (game_id, language_code) DO NOTHING;
