INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shrek Extra Large', 'Shrek: Extra Large is packed with 10 levels, twisted fairy tale characters, cutscenes, and action-packed gameplay. Play as your favorite characters from the movie Shrek or as new fairy tale characters. In order to rescue Princess Fiona, you must explore 10 different fairy tale lands and compete in more than 50 missions. Your character can perform a variety of power moves such as punch, kick, grab, super-flatulance, and belch. When you''re not in combat, you can watch 15 brand-new cutscenes.' FROM games WHERE igdb_id = 3675 ON CONFLICT (game_id, language_code) DO NOTHING;
