INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X-Men: Next Dimension', 'X-Men: Next Dimension is a fighting game and the third game in the X-Men: Mutant Academy game series. Next Dimension expands upon the concept of the first two games by adding several new characters, 3-D maps, and a story mode, which allows the player to fight a series of battles in between short movies that move the plot along. The plot of the story mode is loosely based on the comic story "Operation: Zero Tolerance".' FROM games WHERE igdb_id = 4577 ON CONFLICT (game_id, language_code) DO NOTHING;
