INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Triple Play 2002', 'Step up to the plate and swing for the fences with Triple Play 2002. The action on the field comes to life with real player models and dramatic out-of-play sequences, giving players the chance to experience big game moments such as a game-winning hit or a key strikeout.
