INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario Sunshine', 'Super Mario Sunshine is a Mario action-adventure 3D platformer. It follows Super Mario 64, and is the second 3D Mario platformer. Gameplay features a combination of action and puzzle solving, with numerous stages and multiple episodes to each stage, and plenty of hidden secrets and surprises. This game introduced many recurring characters and bosses in the Mario series, including Toadsworth, Bowser Jr., Petey Piranha, Gooper Blooper, Piantas, Nokis, Shadow Mario, and F.L.U.D.D. Super Mario Sunshine pays homage to Mario''s Italian heritage and upbringing, with many of the locations in the game having Italian names and sometimes referencing Italian culture.' FROM games WHERE igdb_id = 1075 ON CONFLICT (game_id, language_code) DO NOTHING;
