INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mechwarrior-4-mercenaries', 19192, '2002-11-07', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co23rv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc89uv.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MechWarrior 4: Mercenaries', 'The sequel to Mechwarrior 4: Vengeance. When you''re a ''Mech Mercenary, you call the shots. You don''t fight for honor - you fight for cold hard cash, a fierce reputation, and the heart-pounding thrill of the kill. Your allegiance goes to the highest bidder. You answer only to the call of fortune. Your fate is in your hands alone. Select from 4 of the most notorious mercenary units, Kell Hounds, Wolf''s Dragoons, Northwind Highlanders, and Gray Death Legion, to alter your missions, with different outcomes based on your victories. Choose from over 35 different ''Mechs, including 10 new ones. And for the first time ever, your secondary lance allows you to muster 8 ''Mechs into battle simultaneously. Or make a killing in the infamous Solaris VII arenas, where fighting dirty can make you filthy rich. Includes ''Mechs from the Black Knight expansion for Mechwarrior 4, and is fully compatible with Mechwarrior 4 ''Mech Packs. Fight for fame. Fight for fortune. Fight as a Mech Mercenary!' FROM games WHERE igdb_id = 19192 ON CONFLICT (game_id, language_code) DO NOTHING;
