INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('command-conquer-renegade', 706, '2002-02-26', 59, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20ig.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2sp2.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Command & Conquer: Renegade', 'Renegade''s story takes place during the final days of the First Tiberium War originally depicted in Command & Conquer. GDI''s top three Tiberium research specialists have been abducted by the Brotherhood of Nod. The player assumes the role of GDI commando Captain Nick "Havoc" Parker, who is assigned to rescue these experts. He conducts missions which take him all over the world in various countries and climates, both indoor and outdoor, and his actions greatly affect the current state of the war. As the game progresses it is revealed that the specialists have been forced into biochemistry research for the Brotherhood''s top secret "Project Re-Genesis," An attempt to create genetically enhanced super-soldiers with the aid of Tiberium.
