INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Zelda: Four Swords', 'The Legend of Zelda: Four Swords is a multiplayer game in the Zelda series originally released together with The Legend of Zelda: A Link to the Past for the Game Boy Advance. The game has many features not seen in the series and it requires at least two people to play and uses randomly generated dungeons. During the game, players must collect as many Ruppees as possible while solving puzzles and defeating enemies. When enough Ruppees are collected, the Great Fairy will give the players a key to open the unlockable level. At the end of each level, the one who collects the most Ruppees will be the winner.' FROM games WHERE igdb_id = 163572 ON CONFLICT (game_id, language_code) DO NOTHING;
