INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spyro: Enter the Dragonfly', 'Spyro: Enter the Dragonfly is the fourth game in the Spyro the Dragon series and the first Spyro game to be on the PlayStation 2 and Nintendo Gamecube. Gameplay is similar to the previous three console games. The only playable character is Spyro, however he can man several vehicles: Hunter''s Manta Ray and the UFO''s make a return appearance from Year of the Dragon, alongside two new vehicles, the tank and the Spitfire attack plane.
