INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Rangers: Wild Force', 'In Power Rangers Wild Force for Game Boy Advance, young gamers will play as their favorite Power Ranger, this time armed with the strength and characteristics of the Power Animals including the Bison, Tiger, Shark, Eagle and Lion. The top-down, 3D exploration adventure allows players to take on the Org, an ancient race of villains who are out to destroy the balance of nature.' FROM games WHERE igdb_id = 49181 ON CONFLICT (game_id, language_code) DO NOTHING;
