INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DDRMax2: Dance Dance Revolution', 'The dance floor kicks into overdrive with DDRMAX2 Dance Dance Revolution. It is the latest installment of the highly anticipated DDR series and takes the revolution to the masses! Players can customize their own dance steps and workout in an innovative Exercise Mode. DDR is packed with a smash-hit lineup of all-new exclusive songs, licensed music and dance hits. There are cool contemporary game modes and brand new graphical interfaces featuring music videos that will keep everybody movin'' and groovin'' to the pulsating beats. DDR Max 2 also includes links to previous games for special features.' FROM games WHERE igdb_id = 44711 ON CONFLICT (game_id, language_code) DO NOTHING;
