INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Getaway', 'The Getaway is a sandbox crime game set in London. It is inspired by British gangland films Get Carter and Snatch. Initially, the release of the game was to coincide with the launch of the PlayStation 2 in 2000, but was delayed by 27 months due to the difficulty of re-creating large areas of London in high resolution. Parts of The Getaway feature in various episodes of Graham Duff''s Ideal.' FROM games WHERE igdb_id = 8237 ON CONFLICT (game_id, language_code) DO NOTHING;
