INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ESPN International Winter Sports 2002', 'As for the Winter Olympics rapidly approach, ESPN the Games invites gamers to experience all the thrills, chills and spills of cold-air competition with the only multi-event winter sports game available on any platform - ESPN International Winter Sports 2002. Boasting fast-paced events such as Downhill Alpine Skiing, Freestyle Mogul Skiing, Speed Skating, Bobsledding and more, ESPN International Winter Sports 2002 is fully-loaded. Cut through the gates at death-defying speeds in the slalom or bust some big air ski jumping as ESPN International Winter Sports 2002 provides the ultimate gaming experience for the most timid snowbunnies to adventurous hot dogs alike.' FROM games WHERE igdb_id = 3905 ON CONFLICT (game_id, language_code) DO NOTHING;
