INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King''s Quest II: Romancing the Stones', 'King''s Quest II: Romancing the Stones is a remake of King''s Quest II: Romancing the Throne and a follow-up to AGD Interactive''s (formerly Tierra Entertainment) earlier remake of the first game. Similar to its predecessor, it has VGA graphics reminiscent of Sierra''s adventure games of the early 1990''s and a new musical score. The remake retains the general outlines of the original story and the gameplay system, however contains additional locations, expanded dialogue, and new characters. Some of these characters are original, while others are taken from various installments of the series to present a more cohesive view of its overarching story.' FROM games WHERE igdb_id = 77309 ON CONFLICT (game_id, language_code) DO NOTHING;
