INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frogger Beyond', 'Hop into the latest addition to the Frogger franchise with Frogger Beyond, a new adventure that takes you through eight expansive worlds. As the amphibious hero, Frogger, you''ll encounter a wide range of enemies, obstacles, and new challenges. This time, you can snowboard ice-covered mountains, travel through lava caverns, and navigate the depths of outer space. Frogger Beyond revives the series with 40 new enemies, new frog abilities, and hidden areas and power-ups.' FROM games WHERE igdb_id = 3922 ON CONFLICT (game_id, language_code) DO NOTHING;
