INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kamen-rider-ryuki', 44858, '2002-11-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7jz5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc93o1.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kamen Rider Ryuki', 'All over the city, innocent people are being mysteriously abducted, never to be seen again. During his investigations of these incidents, Shinji Kido – an intern at the online news service ORE Journal – discovers one of the Advent Card decks at an apartment where every reflective surface has been covered by newspaper. He is soon sucked into the Mirror World, discovering the terrifying truth behind the disappearances: people are literally being pulled through mirrors by the monsters of the Mirror World so that they may feed. He is about to be killed by a powerful dragon named Dragredder when he is saved by Kamen Rider Knight: Ren Akiyama. Ren seeks to win the Rider War at all costs. He works with a young woman named Yui Kanzaki, who seeks her missing brother: the master of the Rider War, Shiro Kanzaki. Seeing Ren''s strength, Shinji enters the Rider War not for the prize, but so that he may protect innocent people from the threat of the Mirror World, and stop the senseless fighting between the Kamen Riders. With Dragredder as his Contract Monster, he becomes Kamen Rider Ryuki.' FROM games WHERE igdb_id = 44858 ON CONFLICT (game_id, language_code) DO NOTHING;
