INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('james-bond-007-nightfire', 1631, '2002-11-18', 58, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co26dt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hk4wul6d8vu2ozbneo2i.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'James Bond 007: Nightfire', '007: Nightfire is a first-person shooter featuring the character of the British secret agent James Bond and a sequel to Agent Under Fire. The game marked Pierce Brosnan''s fourth appearance as James Bond before the release of his fourth and final Bond film Die Another Day. His likeness was featured in the game, but not his voice, which was provided by Maxwell Caulfield. Overall there are many weapons that the player can carry including grenades of various sorts and other types of explosives. In addition, there are numerous amounts of mounted weapons found throughout the game. As with previous James Bond games, the weapons that appear are based on actual weapons, but with the names changed. Some weapons appear in the console version but not the PC version, and vice-versa.' FROM games WHERE igdb_id = 1631 ON CONFLICT (game_id, language_code) DO NOTHING;
