INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dragon-s-lair-3d-return-to-the-lair', 3898, '2002-11-17', 37, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co22p7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmiu6.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon''s Lair 3D: Return to the Lair', 'Dragon''s Lair 3D: Return to the Lair is an action-adventure video game released in 2002 by Dragonstone Software. The game is based on Cinematronics'' 1983 laserdisc arcade game Dragon''s Lair, and follows a similar story; the hero, Dirk the Daring, must enter the evil wizard Mordroc''s castle to rescue Princess Daphne from Singe the dragon. Many of the characters and locations from the 1983 original make appearances in the game, along with new puzzles, rooms and enemies. Animator and director Don Bluth, who produced the cartoon animation for the arcade original, also produced two new animated sequences for the opening and ending of the game. The game uses cel shading to mimic the distinctive style of the original.' FROM games WHERE igdb_id = 3898 ON CONFLICT (game_id, language_code) DO NOTHING;
