INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shrek Super Party', 'Shrek: Super Party is a party video game released in 2002 by Mass Media. The game is based on the Shrek movie series. This game is also similar to Pac-Man Fever (which has the same developer) and the Mario Party series of games. The characters Shrek, Fiona, Donkey, Lord Farquaad, Thelonius, and Monsieur Hood are available for play. Five realms are available for play, each with its own mini-games: The Keep, The Windmill, The Swamp, The Castle, and The Farm.' FROM games WHERE igdb_id = 3673 ON CONFLICT (game_id, language_code) DO NOTHING;
