INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'State of Emergency', 'In State of Emergency, the player can choose from one of five different characters: Spanky, an ex-gang member; McNeil, a disgruntled ex-cop; Bull, a criminal in prison; Libra, a lawyer; and Phreak, an orphan. The player must complete a variety of missions, ranging from Rescue missions to "Kill This Person" missions to "Blow Up This ..." missions.
