INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shox: Rally Reinvented', 'Arcade rally racing gets fast and furious in the newest addition to the EA SPORTS BIG! line-up. Let it all hang out as you powerslide, get big air, and smash through 20 exotic off-road tracks. Charge with precision and blaze through Shox Zones to win the races within the race. Burn rubber to earn a new turbo-charged ride or wager it all for a chance to win 24 licensed beauties in the ultimate off-road collection.' FROM games WHERE igdb_id = 8265 ON CONFLICT (game_id, language_code) DO NOTHING;
