INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Lord of the Rings: The Two Towers', 'The Lord of the Rings: The Two Towers is an action and adventure game based off of the first two movies of the popular Lord of the Rings series, The Fellowship of the Ring and The Two Towers. Players battle their way through some of the key events of these films as Aragorn, Legolas, and Gimli.' FROM games WHERE igdb_id = 2965 ON CONFLICT (game_id, language_code) DO NOTHING;
