INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ncaa-college-basketball-2k3', 4038, '2002-12-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ue1.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NCAA College Basketball 2K3', 'NCAA College Basketball 2K3 is an American college basketball video game which was initially released on December 2, 2002 for the Xbox, PS2 and GameCube. It is to this day the only title in the series that uses the "College Basketball" designation rather than "College Hoops". It is also the only title for the series to appear on the GameCube and the GameCube''s only college basketball game. It features former Duke Blue Devils guard Jay Williams on the cover. This game was released in very limited quantities and is one of the more difficult GameCube titles to find.' FROM games WHERE igdb_id = 4038 ON CONFLICT (game_id, language_code) DO NOTHING;
