INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom and Jerry in War of the Whiskers', 'Are you ready to kick some butt with Tom and Jerry and friends? With your choice over 75 weapons, you can duke it out in unique levels such as Frankenmouse, a twisted laboratory, or Towering Infurno, an unstable construction site! Be Prepared for the ultimate game of "Cat and Mouse"!' FROM games WHERE igdb_id = 2650 ON CONFLICT (game_id, language_code) DO NOTHING;
