INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Elder Scrolls III: Morrowind', 'First-person WRPG and third mainline entry in the Elder Scrolls franchise in which the player arrives in the island of Vvardenfell, an exotic land plagued by disease-carrying storms and ruled by a godly Tribunal, in the Morrowind province of Tamriel, and takes part in the prophecy foretelling the second coming of Nerevar, who will supposedly save Morrowind from malicious clans both within and outside Vvardenfell.' FROM games WHERE igdb_id = 56 ON CONFLICT (game_id, language_code) DO NOTHING;
