INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Magical Mirror Starring Mickey Mouse', 'One night, a mischievous ghost traps a sleepwalking Mickey Mouse in a magical mirror. Returning to his bed won''t be easy, though, because Mickey must first recover the broken mirror pieces that have been strewn about the house by the prankish poltergeist. Just as in a Mickey cartoon, you will have to outwit enemies and pull gags. You will also be able to uncover special souvenirs, such as Pluto''s collar or Minnie''s bow, which are all displayed in Mickey''s room at the end of the game.' FROM games WHERE igdb_id = 3773 ON CONFLICT (game_id, language_code) DO NOTHING;
