INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Dance Revolution Extreme', 'Dance Dance Revolution Extreme is a music video game by Konami and is the eighth release in the main Dance Dance Revolution (DDR) series. It was released on December 25, 2002 for Japanese arcades, on October 9, 2003 for the Japanese PlayStation 2, and on September 21, 2004 for the North American PlayStation 2. This game is the ninth release in North America, but despite having the same name as its Japanese counterpart, its gameplay and soundtrack is significantly different[1] and won the Video Music Awards in 2005 on MTV for Best Video Game Soundtrack.
