INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Serious Sam: The Second Encounter', 'Serious Sam: The Second Encounter, the highly anticipated arcade action FPS sequel to the Serious Sam: The First Encounter, is a high-adrenaline arcade-action shooter heavily focused on frantic arcade-style single player action. In a world where cyberpunk meets fantasy-fiction and advanced technology is mixed with black magic and psycho-powers, Sam travels through the three beautiful worlds, confronting countless Mental''s minions on his way to the Mental''s base.' FROM games WHERE igdb_id = 858 ON CONFLICT (game_id, language_code) DO NOTHING;
