INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gran Turismo Concept: 2002 Tokyo-Geneva', 'Gran Turismo Concept is a racing video game of the Gran Turismo series for PlayStation 2 which is developed by Polyphony Digital. It is essentially a short version of Gran Turismo 3: A-Spec, but with concept cars that ended up in Gran Turismo 4. It was released in 2002 in Japan, Southeast Asia, Korea, and Europe. For undisclosed reasons, the game was not released in the North American market, although a stripped-down version of it was released in form of Gran Turismo: Nissan 350Z Edition.
