INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fire-emblem-fuuin-no-tsurugi', 1438, '2002-03-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobag0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2d1i.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire Emblem: Fuuin no Tsurugi', 'Fire Emblem: The Binding Blade is a Japanese tactical role-playing game developed by Intelligent Systems and published by Nintendo. The game was released on March 29, 2002 in Japan, is the sixth game in the Fire Emblem series, and the first of three games in the series that have appeared on Nintendo''s Game Boy Advance handheld. It was the last Fire Emblem game to be released exclusively in Japan until the release of Fire Emblem: New Mystery of the Emblem. The Binding Blade was followed by a prequel, Fire Emblem: The Blazing Blade, set twenty years earlier.' FROM games WHERE igdb_id = 1438 ON CONFLICT (game_id, language_code) DO NOTHING;
