INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil', 'Resident Evil is the 2002 remake of the original 1996 video game of the same name featuring various improvements and gameplay overhaul. The game features all-new graphics and sound, and also incorporates gameplay elements from the earlier installments. While the overall plot remained mostly unchanged, several new areas and rooms were added to the game. This remake also features many additional modes, secrets and various endings over the original.' FROM games WHERE igdb_id = 24869 ON CONFLICT (game_id, language_code) DO NOTHING;
