INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hugo: The Evil Mirror', 'The evil witch Scylla has trapped Hugo in a mirror, and now it''s up to you to rescue him. In Hugo and the Evil Mirror, you must save Hugo in three different worlds, each guarded by dangerous monsters. Use the freeze gun to turn enemies into ice cubes, and then push them over the edge of the levels or combine them with other frozen monsters to gain power-ups.' FROM games WHERE igdb_id = 6438 ON CONFLICT (game_id, language_code) DO NOTHING;
