INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beach Head 2002', 'BEACHHEAD 2002 follows on the success of BEACHHEAD 2000 with ease of use and hard-core, non-stop 3D shooting action in a photorealistic and accurate environment. Players will be assigned to an inland defense perimeter, protecting a command post to repel an expected airborne assault. It has more depth and game play variations, smarter troops and with more weapons to choose from. Continuous day and night fighting with searchlights and night flares and much, much more.' FROM games WHERE igdb_id = 27660 ON CONFLICT (game_id, language_code) DO NOTHING;
