INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spyro 2: Season of Flame', 'Spyro 2: Season of Flame is the sequel to Spyro: Season of Ice. All the old characters from previous games are there, with Hunter and Bianca, and the player can also control Sheila the Kangaroo and Agent 9. Spyro has a few unusual abilities in this GBA game, including a fire/ice breath toggle. Some items can only be affected by one or the other. Unlike the PSX games, Spyro is presented primarily in an isometric view.' FROM games WHERE igdb_id = 1588 ON CONFLICT (game_id, language_code) DO NOTHING;
