INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'High Heat Major League Baseball 2003', 'High Heat Major League Baseball 2003 was the second-to-last of a series of baseball computer games, released on PlayStation 2, PC, and Game Boy Advance. The game, featuring the official licensed team and player names from all 30 MLB teams, was created by games company 3DO, who later filed for bankruptcy in May 2003.[4' FROM games WHERE igdb_id = 6435 ON CONFLICT (game_id, language_code) DO NOTHING;
