INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'UEFA Champions League Season 2001/2002', 'Installment in the UEFA soccer simulation series, featuring rosters and up-to-date data from the 2001/2002 season. This Season''s UEFA Champions League gives you the unique opportunity to play against Europe''s leading clubs, while also offering you the option to take on previous winners, since 1960. The Official Video Game of The UEFA CHAMPIONS LEAGUE Season 2000/2001. Developed by Silicon Dreams, UEFA Champions League Season 2001/2002 was only released in the Europe market.' FROM games WHERE igdb_id = 22058 ON CONFLICT (game_id, language_code) DO NOTHING;
