INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Soccer Mania', 'In LEGO Soccer Mania, you can play soccer any way you want. Start by building your own team from over 150 different players, ranging from pirates and knights to Arctic explorers. Then, practice your shots in the Skill Zone. Once you''re ready for the big game, you can challenge the opposition across various action-packed environments, using power-ups to gain the competitive edge. Lego Soccer Mania takes you on wild tracks with various themes, from the Wild West to Mars.' FROM games WHERE igdb_id = 49221 ON CONFLICT (game_id, language_code) DO NOTHING;
