INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Arena', 'Dark Arena is 20 levels of terrifying, non-stop action. You play the role of Angela Bradshaw, a special forces agent who is trapped in the bowels of a deadly labyrinth of maze-like passages crawling with bloodthirsty, genetic horrors. Armed with a deadly array of futuristic weaponry and your wits, you must make your escape.' FROM games WHERE igdb_id = 6367 ON CONFLICT (game_id, language_code) DO NOTHING;
