INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiger Woods PGA Tour 2003', 'Tiger Woods PGA Tour 2003 is a 2002 golf video game released by EA Sports. Among the features in the game is the Tiger Challenge, in which the player is matched against real or fantasy golfers one at a time. There is also a scenario mode with 50 scenarios, challenging the players'' skills in a variety of realistic settings. The game also includes a tournament mode that simulates a season on the PGA Tour.' FROM games WHERE igdb_id = 904 ON CONFLICT (game_id, language_code) DO NOTHING;
