INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SpongeBob SquarePants: Revenge of the Flying Dutchman', 'A treasure turns into a terror in SpongeBob Squarepants: Revenge of the Flying Dutchman. While cruising through Bikini Bottom, SpongeBob discovers several treasure chests. Ignoring the warning signs, SpongeBob opens the chests, only to discover he has released the Flying Dutchman--an angry ghost that now wants to make SpongeBob and his friends part of his crew. As you help SpongeBob stop the Dutchman from wreaking havoc in Bikini Bottom, you change costumes, collect gold coins, and interact with all your favorite characters from the TV show.' FROM games WHERE igdb_id = 2762 ON CONFLICT (game_id, language_code) DO NOTHING;
