INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prisoner of War', 'Prisoner of War captures the intrigue, danger and heroism of Allied escape attempts from prisoner of war camps during World War II, including Colditz - the Germans highest security "escape-proof" camp. Gameplay delivers a tense 3rd person stealth adventure game where bravery, stealth and cunning will win the day.' FROM games WHERE igdb_id = 5990 ON CONFLICT (game_id, language_code) DO NOTHING;
