INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Men in Black II: Alien Escape', 'Men in Black 2: Alien Escape is a fast-paced third-person perspective action game liberally infused with the trademark humor of the smash 1997 movie and the upcoming sequel. The game is divided into five distinct episodes, including a Nuclear Station, the Docks and the streets of Manhattan. All episodes include numerous levels and challenges to complete prior to progressing through the game.' FROM games WHERE igdb_id = 4003 ON CONFLICT (game_id, language_code) DO NOTHING;
