INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kaan: Barbarian''s Blade', 'Asaquan, the realm of Queen Xithanna, is being attacked by the troops of Tothum Siptet, the evil sorcerer of Syrkonia. As soon as Kaan arrives on the scene, he applies all his fighting energy into attempting to repel the attack. But he is already too late: the town has been pillaged, put to fire and sword by the sorcerer''s troops.' FROM games WHERE igdb_id = 43564 ON CONFLICT (game_id, language_code) DO NOTHING;
