INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvel''s The Invincible Iron Man', 'The Invincible Iron Man allows you to experience the powers of Iron Man as he fights hordes of enemies while tracking down the super-villains who have stolen his battle suit technology. Using a variety of battle suit weaponry he navigates diverse levels that are filled with environmental obstacles and imminent danger. Multiple power-ups, unlockable bonus items and special pick-ups provide fans with the ultimate Iron Man experience.' FROM games WHERE igdb_id = 49231 ON CONFLICT (game_id, language_code) DO NOTHING;
