INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Medabots: Metabee', 'Join Ikki as he begins his journey as a Medafighter and tries to save his hometown of Riverview City from the evil Rubberobo Gang. Ikki must solve various mysteries with the help of his friends and the Phantom Renegade. Interact with characters and control Medabots popular in the Medabots TV animated series. Can Ikki save the world from the treacherous Rubberobo Gang and become the #1 ranked Medafighter...It is all up to you!' FROM games WHERE igdb_id = 7583 ON CONFLICT (game_id, language_code) DO NOTHING;
