INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lufia: The Ruins of Lore', 'This exciting new chapter in the Lufia saga follows the adventures of Eldin, Torma, and Rami, a group of friends and would-be hunters as they set out in search of treasure, only to discover that fate has much more in store for them! Will they be able to solve the mysteries of the ancient ruins and stop the power-hungry leader Ragule from resurrecting the ancient beast, or will Ragules ambitions be realized at the expense of mankind? Prepare for the Adventure of a Lifetime!' FROM games WHERE igdb_id = 1180 ON CONFLICT (game_id, language_code) DO NOTHING;
