INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Swingerz Golf', 'Tee up on 6 courses featuring diverse terrains and seasonal weather condition. Compete with 14 offbeat golfers, each with distinct personalities and golfing abilities. Experience realistic golfing physics with Ace Golf''s intuitive analog swing system. Master multiple modes of play for 1-4 golfers including Tournament, Stroke, Match and Short Course. Win tournaments and beat rivals to upgrade your golf gear. Enjoy golfing action with addictive mini games.' FROM games WHERE igdb_id = 4192 ON CONFLICT (game_id, language_code) DO NOTHING;
