INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MLB Slugfest 2003', 'MLB Slugfest is a series of baseball games developed by Sports Mogul, Gratuitous Games and Midway Games, and released by Midway Games for major console systems such as PlayStation 2, Nintendo GameCube, and Xbox. The game bills itself as a more "street" style baseball game, including more mature / aggressive themes, the ability to attack other players, and urban-styled in-game commentary.' FROM games WHERE igdb_id = 47334 ON CONFLICT (game_id, language_code) DO NOTHING;
