INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s PK: Out of the Shadows', 'The PK character may be unfamiliar to American audiences, but he is popular in Italy (and some other parts of Europe) through a series of comic books. This game is a simple 3rd person action shooter game. You control PK as he targets Evronian soldiers with his blasters, jumps through colorful environments, and rescues captured scientists.' FROM games WHERE igdb_id = 3887 ON CONFLICT (game_id, language_code) DO NOTHING;
