INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Duke Nukem: Manhattan Project', 'Duke Nukem takes his Mighty Boot to the Big Apple. Using GLOPP (Gluon Liquid Omega-Phased Plasma), the maniacal mech Morphix has transformed the creatures of New York City into an army of bloodthirsty mutants. In Duke Nukem: Manhattan Project, Duke must deploy WIN (Weapons, Insults and Name-Calling) to rid the city of goo-based bad guys, and return peace and tranquility to The City That Never Sleeps.' FROM games WHERE igdb_id = 8505 ON CONFLICT (game_id, language_code) DO NOTHING;
